function base52Encode(data: Buffer, alphabet: string = REVERSED52): string {
    const firstChar = alphabet[0];
    const leadingZeros = leadingZeroBytes(data);
    let result = firstChar.repeat(leadingZeros);

    const nonZeroData = data.slice(leadingZeros);
    if (nonZeroData.length === 0) {
        return result;
    }

    let value = 0n;
    for (const byte of nonZeroData) {
        value = (value << 8n) | BigInt(byte);
    }

    let encoded = '';
    while (value > 0n) {
        const remainder = Number(value % 52n);
        encoded = alphabet[remainder] + encoded;
        value = value / 52n;
    }

    return result + encoded;
}
