// add (i + 1) to the distance (1-indexed weight).
// Strings must be equal length.

golden_completion:
function weightedHamming(a: string, b: string): number {
    let dist = 0;
    for (let i = 0; i < a.length; i++) {
        if (a[i] !== b[i]) dist += i + 1;
    }
    return dist;
}

